1	/**
2	 * Modal de conferência de CHEGADA na loja (espelho da expedição).
3	 *
4	 * Quando o caminhão chega na loja destino, o operador entra com a requisição
5	 * carregada (apenas itens da requisição da própria loja). Para cada item:
6	 *  - Bipa o QR da caixa → RPC bipar_etiqueta(uid,'entrada',{loja_id})
7	 *    + INSERT movimentacao + atualiza requisicoes_itens.quantidade_recebida
8	 *    + recebida_via='bip', recebida_at, recebida_por.
9	 *  - OU marca manual (sem etiqueta): apenas atualiza recebida_via='manual'
10	 *    + quantidade_recebida = quantidade_solicitada (sem mexer em movimentacoes,
11	 *    o estoque entra via fluxo paralelo).
12	 *
13	 * Salva parcial. Operador pode fechar e voltar depois — state hidrata da DB.
14	 * "Concluir chegada" preenche requisicoes.chegada_concluida_at.
15	 */
16	import { useEffect, useMemo, useRef, useState } from "react";
17	import { Dialog, DialogContent, DialogTitle } from "@/shared/ui/dialog";
18	import { Button } from "@/shared/ui/button";
19	import { Input } from "@/shared/ui/input";
20	import { ScrollArea } from "@/shared/ui/scroll-area";
21	import {
22	  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
23	  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
24	} from "@/shared/ui/alert-dialog";
25	import {
26	  ArrowLeft, Bluetooth, Camera, ScanBarcode, Package, MapPin, CheckCircle2,
27	  AlertTriangle, Hand, Boxes,
28	} from "lucide-react";
29	import { toast } from "sonner";
30	import { cn } from "@/shared/lib/utils";
31	import { supabase } from "@/integrations/supabase/client";
32	import {
33	  useEtiquetaScanner, playSuccessSound, playErrorSound, playWarningSound,
34	  formatBipError, type ScannedPayload,
35	} from "@/shared/hooks/useEtiquetaScanner";
36	import { CameraScannerStatus } from "@/features/logistica/ui/CameraScannerStatus";
37	
38	export interface ChegadaItem {
39	  id: number; // id em requisicoes_itens
40	  nome_produto: string;
41	  masterId: number | null;
42	  quantidade_solicitada: number;
43	  quantidade_enviada: string; // o que foi expedido pela fábrica
44	  quantidade_recebida: string; // estado persistido (parcial entre sessões)
45	  recebida_via: "bip" | "manual" | null;
46	  recebida_at: string | null;
47	}
48	
49	interface BipBuffer {
50	  itemId: number;
51	  uid: string;
52	  qty: number;
53	  embalagem: string | null;
54	  bipadoAt: number;
55	}
56	
57	interface ManualState {
58	  open: boolean;
59	  item?: ChegadaItem;
60	  quantidade: string;
61	  resolve?: (ok: boolean, qty: number) => void;
62	}
63	
64	interface Props {
65	  isOpen: boolean;
66	  onClose: () => void;
67	  requisicaoId: number;
68	  requisicaoNome: string;
69	  lojaDestinoId: number;
70	  lojaDestinoNome: string;
71	  items: ChegadaItem[];
72	  /** Quando o operador clica em "Concluir chegada" — pai recarrega/atualiza UI. */
73	  onConcluida?: () => void;
74	}
75	
76	export function RequisicaoChegadaModal({
77	  isOpen, onClose, requisicaoId, requisicaoNome,
78	  lojaDestinoId, lojaDestinoNome, items, onConcluida,
79	}: Props) {
80	  const [localItems, setLocalItems] = useState<ChegadaItem[]>([]);
81	  const [bipsLog, setBipsLog] = useState<BipBuffer[]>([]);
82	  const uidsLidosRef = useRef<Set<string>>(new Set());
83	  const [manual, setManual] = useState<ManualState>({ open: false, quantidade: "" });
84	  const [concluindo, setConcluindo] = useState(false);
85	
86	  useEffect(() => {
87	    if (!isOpen) return;
88	    setLocalItems(items.map((i) => ({ ...i })));
89	    setBipsLog([]);
90	    uidsLidosRef.current = new Set();
91	  }, [isOpen, items]);
92	
93	  // Marca a flag de chegada_iniciada_at na primeira interação
94	  const marcarChegadaIniciada = async () => {
95	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
96	    await (supabase.from("requisicoes") as any)
97	      .update({ chegada_iniciada_at: new Date().toISOString() })
98	      .eq("id", requisicaoId)
99	      .is("chegada_iniciada_at", null);
100	  };
101	
102	  const updateItemRow = async (
103	    itemId: number,
104	    novaQtd: string,
105	    via: "bip" | "manual",
106	    userId: string | null,
107	  ) => {
108	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
109	    return (supabase.from("requisicoes_itens") as any)
110	      .update({
111	        quantidade_recebida: novaQtd,
112	        recebida_via: via,
113	        recebida_at: new Date().toISOString(),
114	        recebida_por: userId,
115	      })
116	      .eq("id", itemId);
117	  };
118	
119	  const handleBip = async (payload: ScannedPayload) => {
120	    if (!payload.uid) {
121	      playErrorSound();
122	      toast.error("Etiqueta sem UID — não rastreável");
123	      return;
124	    }
125	    if (uidsLidosRef.current.has(payload.uid)) {
126	      playErrorSound();
127	      toast.error("Caixa já bipada nesta chegada");
128	      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
129	      return;
130	    }
131	
132	    await marcarChegadaIniciada();
133	
134	    // RPC: valida transição em_transito → recebida
135	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
136	    const { data: rpcRaw, error: rpcErr } = await (supabase.rpc as any)("bipar_etiqueta", {
137	      p_uid: payload.uid,
138	      p_etapa: "entrada",
139	      p_contexto: {
140	        loja_id: lojaDestinoId,
141	        referencia_tipo: "requisicao_chegada",
142	        referencia_id: String(requisicaoId),
143	        payload,
144	      },
145	    });
146	    if (rpcErr) {
147	      playErrorSound();
148	      toast.error(`Falha no bip: ${rpcErr.message}`);
149	      return;
150	    }
151	    const result = rpcRaw as {
152	      ok: boolean; erro?: string;
153	      etiqueta?: { produto_master_id: number; produto_nome_snapshot?: string | null; lote_id?: string | null; quantidade_interna?: number; embalagem_nome?: string | null };
154	      alertas?: string[];
155	    };
156	    if (!result?.ok || !result.etiqueta) {
157	      playErrorSound();
158	      toast.error(formatBipError(result?.erro, "entrada"));
159	      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
160	      return;
161	    }
162	    (result.alertas ?? []).forEach((a) => {
163	      playWarningSound();
164	      toast.warning(a);
165	    });
166	
167	    const et = result.etiqueta;
168	    const qty = Number(et.quantidade_interna ?? payload.qty ?? 1);
169	    const target = localItems.find((i) => i.masterId === et.produto_master_id);
170	    if (!target) {
171	      playWarningSound();
172	      if (navigator.vibrate) navigator.vibrate([100, 50, 100]);
173	      toast.warning(`${et.produto_nome_snapshot || `#${et.produto_master_id}`} NÃO está nesta requisição`);
174	      uidsLidosRef.current.add(payload.uid);
175	      return;
176	    }
177	
178	    // Soma à quantidade_recebida atual
179	    const baseAtual = Number(target.quantidade_recebida || "0") || 0;
180	    const novaQtdNum = baseAtual + qty;
181	
182	    // INSERT movimentacao (entrada de estoque)
183	    const { data: { user } } = await supabase.auth.getUser();
184	    const { data: estoqueAtual } = await supabase
185	      .from("estoque")
186	      .select("quantidade_atual")
187	      .eq("produto_master_id", et.produto_master_id)
188	      .eq("loja_id", lojaDestinoId)
189	      .maybeSingle();
190	    const anterior = (estoqueAtual as { quantidade_atual?: number } | null)?.quantidade_atual ?? 0;
191	    const nova = anterior + qty;
192	
193	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
194	    const { error: movErr } = await (supabase.from("movimentacoes") as any).insert({
195	      produto_master_id: et.produto_master_id,
196	      tipo_movimentacao: "entrada",
197	      quantidade: qty,
198	      quantidade_anterior: anterior,
199	      quantidade_nova: nova,
200	      motivo: "recebimento",
201	      observacoes: `Chegada req #${requisicaoId} — UID ${payload.uid}`,
202	      data_movimentacao: new Date().toISOString(),
203	      loja_id: lojaDestinoId,
204	      lote_id: et.lote_id,
205	      etiqueta_qr_uid: payload.uid,
206	    });
207	    if (movErr) {
208	      playErrorSound();
209	      toast.error(`Erro ao registrar entrada: ${movErr.message}`);
210	      return;
211	    }
212	
213	    // Atualiza linha da requisição
214	    const { error: upErr } = await updateItemRow(target.id, String(novaQtdNum), "bip", user?.id ?? null);
215	    if (upErr) {
216	      playErrorSound();
217	      toast.error(`Erro ao salvar conferência: ${upErr.message}`);
218	      return;
219	    }
220	
221	    playSuccessSound();
222	    if (navigator.vibrate) navigator.vibrate(80);
223	    toast.success(`${target.nome_produto} +${qty} un (${et.embalagem_nome || "Un"})`);
224	
225	    setLocalItems((prev) =>
226	      prev.map((i) => i.id === target.id
227	        ? { ...i, quantidade_recebida: String(novaQtdNum), recebida_via: "bip", recebida_at: new Date().toISOString() }
228	        : i),
229	    );
230	    setBipsLog((prev) => [
231	      { itemId: target.id, uid: payload.uid, qty, embalagem: et.embalagem_nome ?? null, bipadoAt: Date.now() },
232	      ...prev,
233	    ]);
234	    uidsLidosRef.current.add(payload.uid);
235	  };
236	
237	  const scanner = useEtiquetaScanner({
238	    enabled: isOpen,
239	    onScan: handleBip,
240	    cameraElementId: "chegada-qr-reader",
241	    onInvalid: () => toast.error("QR ilegível"),
242	    onDuplicate: () => {
243	      playErrorSound();
244	      toast.error("Esta etiqueta já foi bipada");
245	    },
246	  });
247	
248	  const askManual = (item: ChegadaItem) => {
249	    const restante = Math.max(0, item.quantidade_solicitada - (Number(item.quantidade_recebida || "0") || 0));
250	    setManual({
251	      open: true,
252	      item,
253	      quantidade: String(restante > 0 ? restante : item.quantidade_solicitada),
254	    });
255	  };
256	
257	  const confirmManual = async () => {
258	    if (!manual.item) return;
259	    const qty = Number(manual.quantidade);
260	    if (!Number.isFinite(qty) || qty < 0) {
261	      toast.error("Quantidade inválida");
262	      return;
263	    }
264	    await marcarChegadaIniciada();
265	    const { data: { user } } = await supabase.auth.getUser();
266	    const { error } = await updateItemRow(manual.item.id, String(qty), "manual", user?.id ?? null);
267	    if (error) {
268	      toast.error(`Erro ao salvar: ${error.message}`);
269	      return;
270	    }
271	    setLocalItems((prev) =>
272	      prev.map((i) => i.id === manual.item!.id
273	        ? { ...i, quantidade_recebida: String(qty), recebida_via: "manual", recebida_at: new Date().toISOString() }
274	        : i),
275	    );
276	    setManual({ open: false, quantidade: "" });
277	    toast.success(`${manual.item.nome_produto}: ${qty} un (manual)`);
278	  };
279	
280	  const concluir = async () => {
281	    setConcluindo(true);
282	    const { data: { user } } = await supabase.auth.getUser();
283	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
284	    const { error } = await (supabase.from("requisicoes") as any)
285	      .update({
286	        chegada_concluida_at: new Date().toISOString(),
287	        chegada_concluida_por: user?.id ?? null,
288	      })
289	      .eq("id", requisicaoId);
290	    setConcluindo(false);
291	    if (error) {
292	      toast.error(`Erro ao concluir: ${error.message}`);
293	      return;
294	    }
295	    toast.success("Chegada concluída.");
296	    onConcluida?.();
297	    onClose();
298	  };
299	
300	  const stats = useMemo(() => {
301	    const totalItens = localItems.length;
302	    const conferidos = localItems.filter((i) => (Number(i.quantidade_recebida || "0") || 0) > 0).length;
303	    const totalSolicitado = localItems.reduce((acc, i) => acc + (i.quantidade_solicitada || 0), 0);
304	    const totalRecebido = localItems.reduce((acc, i) => acc + (Number(i.quantidade_recebida || "0") || 0), 0);
305	    const caixasBipadas = bipsLog.length;
306	    const allConferidos = totalItens > 0 && conferidos === totalItens;
307	    return { totalItens, conferidos, totalSolicitado, totalRecebido, caixasBipadas, allConferidos };
308	  }, [localItems, bipsLog]);
309	
310	  return (
311	    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
312	      <DialogContent data-mia-modal="conferir-chegada-requisicao-nome" className="max-w-[100vw] sm:max-w-[98vw] w-full h-[100dvh] sm:h-[95vh] p-0 flex flex-col overflow-hidden bg-background sm:rounded-[1.5rem] rounded-none">
313	        {/* Header */}
314	        <div className="flex items-center justify-between gap-2 px-3 sm:px-5 py-2 sm:py-3 flex-shrink-0 border-b border-border/50">
315	          <div className="flex items-center gap-2 sm:gap-3 min-w-0 flex-1">
316	            <Button data-mia-action="close" variant="ghost" size="icon" onClick={onClose} className="rounded-2xl hover:bg-[#57715B]/10 h-11 w-11 flex-shrink-0">
317	              <ArrowLeft className="w-5 h-5 text-[#57715B]" />
318	            </Button>
319	            <div className="h-10 w-10 rounded-2xl bg-[#57715B]/10 flex items-center justify-center flex-shrink-0">
320	              <ScanBarcode className="h-5 w-5 text-[#57715B]" />
321	            </div>
322	            <div className="min-w-0 flex-1">
323	              <DialogTitle className="text-base sm:text-lg font-bold text-[#57715B] dark:text-[#E6DCCF] truncate">
324	                Conferir chegada · {requisicaoNome}
325	              </DialogTitle>
326	              <p className="text-[11px] sm:text-xs text-muted-foreground flex items-center gap-1 truncate">
327	                <MapPin className="w-3 h-3 flex-shrink-0" /> <span className="truncate">{lojaDestinoNome}</span>
328	              </p>
329	            </div>
330	          </div>
331	          <div className="flex p-1 rounded-xl bg-muted/50 dark:bg-zinc-800 flex-shrink-0">
332	            <button
333	              onClick={() => scanner.setScanMode("bluetooth")}
334	              aria-label="Scanner Bluetooth"
335	              className={cn(
336	                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
337	                scanner.scanMode === "bluetooth" ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm" : "text-muted-foreground hover:text-foreground",
338	              )}
339	            >
340	              <Bluetooth className="h-4 w-4" /> <span className="hidden sm:inline">Scanner</span>
341	            </button>
342	            <button
343	              onClick={() => scanner.setScanMode("camera")}
344	              aria-label="Scanner por câmera"
345	              className={cn(
346	                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
347	                scanner.scanMode === "camera" ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm" : "text-muted-foreground hover:text-foreground",
348	              )}
349	            >
350	              <Camera className="h-4 w-4" /> <span className="hidden sm:inline">Câmera</span>
351	            </button>
352	          </div>
353	        </div>
354	
355	        {/* Stats */}
356	        <div className="px-3 sm:px-5 py-3 flex-shrink-0 border-b border-border/50 grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-3">
357	          <Stat label="Itens conferidos" value={`${stats.conferidos}/${stats.totalItens}`} />
358	          <Stat label="Caixas bipadas" value={String(stats.caixasBipadas)} icon={<Boxes className="w-3 h-3" />} />
359	          <Stat label="Un. recebidas" value={`${stats.totalRecebido}/${stats.totalSolicitado}`} />
360	          <Stat label="Bips" value={String(stats.caixasBipadas)} />
361	        </div>
362	
363	        {/* Scanner input invisível */}
364	        {scanner.scanMode === "bluetooth" && <input {...scanner.inputProps} />}
365	
366	        {/* Body */}
367	        <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
368	          {scanner.scanMode === "camera" ? (
369	            <div className="w-full md:w-[260px] flex-shrink-0 border-b md:border-b-0 md:border-r border-border/50 bg-black overflow-hidden relative">
370	              <div id={scanner.cameraElementId} className="w-full h-[200px] md:h-full" />
371	              <CameraScannerStatus
372	                starting={scanner.cameraStarting}
373	                error={scanner.cameraError}
374	                onRetry={scanner.retryCamera}
375	              />
376	            </div>
377	          ) : (
378	            <div
379	              className="w-full md:w-[200px] flex-shrink-0 border-b md:border-b-0 md:border-r border-border/50 flex flex-col items-center justify-center p-5 cursor-pointer"
380	              onClick={() => document.querySelector<HTMLInputElement>("input[autofocus]")?.focus()}
381	            >
382	              <div className="w-20 h-20 rounded-full bg-[#57715B]/10 flex items-center justify-center relative">
383	                <Bluetooth className="w-9 h-9 text-[#57715B]" />
384	                <div className="absolute inset-0 rounded-full border-[3px] border-[#57715B]/20 border-t-[#57715B] animate-spin" style={{ animationDuration: "3s" }} />
385	              </div>
386	              <h3 className="text-sm font-bold text-[#57715B] dark:text-[#E6DCCF] mt-4">Aguardando bip…</h3>
387	              <p className="text-[11px] text-muted-foreground text-center mt-1">Sem etiqueta? Marque manual no item.</p>
388	            </div>
389	          )}
390	
391	          {/* Lista de itens da requisição */}
392	          <div className="flex-1 flex flex-col overflow-hidden">
393	            <ScrollArea className="flex-1">
394	              <div className="p-2.5 space-y-2">
395	                {localItems.length === 0 ? (
396	                  <div className="flex flex-col items-center justify-center py-16 text-muted-foreground/40">
397	                    <Package className="w-12 h-12 mb-2" />
398	                    <p className="text-sm font-semibold">Sem itens nessa requisição</p>
399	                  </div>
400	                ) : (
401	                  localItems.map((item) => (
402	                    <ItemRow key={item.id} item={item} onMarcarManual={() => askManual(item)} />
403	                  ))
404	                )}
405	              </div>
406	            </ScrollArea>
407	          </div>
408	        </div>
409	
410	        {/* Footer */}
411	        <div
412	          className="px-3 sm:px-5 py-3 border-t border-border/50 flex items-center justify-between gap-2 flex-shrink-0"
413	          style={{ paddingBottom: "calc(env(safe-area-inset-bottom) + 12px)" }}
414	        >
415	          <p className="text-[11px] sm:text-xs text-muted-foreground truncate">
416	            {stats.allConferidos
417	              ? "Todos os itens conferidos."
418	              : `${stats.totalItens - stats.conferidos} item(ns) pendente(s).`}
419	          </p>
420	          <div className="flex gap-2 flex-shrink-0">
421	            <Button data-mia-action="close" onClick={onClose} variant="outline" className="h-11">Salvar e fechar</Button>
422	            <Button data-mia-action="concluir"
423	              onClick={concluir}
424	              disabled={concluindo}
425	              className={cn("h-11", stats.allConferidos ? "bg-emerald-600 hover:bg-emerald-700" : "bg-[#57715B] hover:bg-[#57715B]/90")}
426	            >
427	              {concluindo ? "Concluindo…" : "Concluir chegada"}
428	            </Button>
429	          </div>
430	        </div>
431	      </DialogContent>
432	
433	      {/* Manual entry */}
434	      <AlertDialog open={manual.open} onOpenChange={(open) => !open && setManual((s) => ({ ...s, open: false }))}>
435	        <AlertDialogContent>
436	          <AlertDialogHeader>
437	            <AlertDialogTitle className="flex items-center gap-2">
438	              <Hand className="w-5 h-5" /> Marcar manual
439	            </AlertDialogTitle>
440	            <AlertDialogDescription asChild>
441	              <div className="space-y-3 pt-2">
442	                <p className="font-semibold text-foreground">{manual.item?.nome_produto}</p>
443	                <p className="text-xs text-muted-foreground">
444	                  Pedido: {manual.item?.quantidade_solicitada} un · Já recebido: {manual.item?.quantidade_recebida || 0} un
445	                </p>
446	                <div>
447	                  <label className="text-xs uppercase tracking-wider font-bold text-muted-foreground block mb-1">
448	                    Quantidade recebida (un)
449	                  </label>
450	                  <Input
451	                    type="number"
452	                    min="0"
453	                    step="any"
454	                    value={manual.quantidade}
455	                    onChange={(e) => setManual((s) => ({ ...s, quantidade: e.target.value }))}
456	                    autoFocus
457	                    className="h-11 text-lg font-bold"
458	                  />
459	                </div>
460	                <p className="text-xs text-amber-700 bg-amber-50 dark:bg-amber-900/20 rounded-md p-2">
461	                  Marcar manual NÃO gera movimentação de estoque automática (sem etiqueta = sem rastreabilidade).
462	                </p>
463	              </div>
464	            </AlertDialogDescription>
465	          </AlertDialogHeader>
466	          <AlertDialogFooter>
467	            <AlertDialogCancel onClick={() => setManual((s) => ({ ...s, open: false }))}>Cancelar</AlertDialogCancel>
468	            <AlertDialogAction onClick={confirmManual}>Confirmar</AlertDialogAction>
469	          </AlertDialogFooter>
470	        </AlertDialogContent>
471	      </AlertDialog>
472	    </Dialog>
473	  );
474	}
475	
476	function Stat({ label, value, icon }: { label: string; value: string | number; icon?: React.ReactNode }) {
477	  return (
478	    <div className="text-center min-w-0">
479	      <p className="text-[9px] sm:text-[10px] uppercase tracking-widest text-muted-foreground font-bold truncate flex items-center gap-1 justify-center">
480	        {icon}{label}
481	      </p>
482	      <p className="text-xl sm:text-2xl font-black tabular-nums text-[#57715B]">{value}</p>
483	    </div>
484	  );
485	}
486	
487	function ItemRow({ item, onMarcarManual }: { item: ChegadaItem; onMarcarManual: () => void }) {
488	  const recebido = Number(item.quantidade_recebida || "0") || 0;
489	  const solicitado = item.quantidade_solicitada || 0;
490	  const enviado = Number(item.quantidade_enviada || "0") || 0;
491	  const pct = solicitado > 0 ? Math.min(100, Math.round((recebido / solicitado) * 100)) : 0;
492	  const status: "vazio" | "parcial" | "completo" | "excesso" =
493	    recebido === 0 ? "vazio"
494	      : recebido > solicitado ? "excesso"
495	      : recebido >= solicitado ? "completo"
496	      : "parcial";
497	  const ring = status === "completo" ? "border-emerald-500/40 bg-emerald-500/5"
498	    : status === "excesso" ? "border-amber-500/40 bg-amber-500/5"
499	    : status === "parcial" ? "border-[#57715B]/30 bg-[#57715B]/5"
500	    : "border-border/50";
501	  const bg = status === "completo" ? "bg-emerald-500"
502	    : status === "excesso" ? "bg-amber-500"
503	    : status === "parcial" ? "bg-[#57715B]"
504	    : "bg-zinc-300 dark:bg-zinc-700";
505	  return (
506	    <div className={cn("rounded-xl border-2 p-3", ring)}>
507	      <div className="flex items-start justify-between gap-2 mb-1.5">
508	        <div className="min-w-0 flex-1">
509	          <p className="text-sm font-semibold leading-tight truncate flex items-center gap-2">
510	            {status === "completo" && <CheckCircle2 className="w-4 h-4 text-emerald-600 flex-shrink-0" />}
511	            {status === "excesso" && <AlertTriangle className="w-4 h-4 text-amber-600 flex-shrink-0" />}
512	            <span className="truncate">{item.nome_produto}</span>
513	          </p>
514	          <p className="text-[11px] text-muted-foreground mt-0.5">
515	            Pedido <b>{solicitado}</b> un · Expedido <b>{enviado || 0}</b> un
516	            {item.recebida_via && (
517	              <span className={cn(
518	                "ml-2 inline-block px-1.5 py-0.5 rounded text-[9px] font-bold uppercase tracking-wider",
519	                item.recebida_via === "bip"
520	                  ? "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-300"
521	                  : "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-300",
522	              )}>
523	                {item.recebida_via}
524	              </span>
525	            )}
526	          </p>
527	        </div>
528	        <div className="flex items-center gap-2 flex-shrink-0">
529	          <span className={cn(
530	            "text-sm font-bold tabular-nums",
531	            status === "completo" ? "text-emerald-700"
532	              : status === "excesso" ? "text-amber-700"
533	              : "text-foreground",
534	          )}>
535	            {recebido}/{solicitado}
536	          </span>
537	          <Button data-mia-action="marcar-manual" size="sm" variant="outline" className="h-8 gap-1 text-[11px]" onClick={onMarcarManual}>
538	            <Hand className="w-3 h-3" /> Manual
539	          </Button>
540	        </div>
541	      </div>
542	      <div className="w-full h-1.5 bg-zinc-100 dark:bg-zinc-800 rounded-full overflow-hidden">
543	        <div className={cn("h-full rounded-full transition-all duration-500", bg)} style={{ width: `${pct}%` }} />
544	      </div>
545	    </div>
546	  );
547	}
