 * Utilitários de logística: normalização de status de requisições e
 * geração de etapas (stops) para a timeline de expedições.
 *
 * O sistema usa **3 estados padronizados** para requisições:
 *
 * | Estado         | Significado                     |
 * |----------------|---------------------------------|
 * | `em_fila`      | Aguardando início da separação  |
 * | `em_progresso` | Separação em andamento          |
 * | `finalizada`   | Separação concluída             |
 *
 * Valores legados (`concluida`, `aprovada`, `entregue`, `separacao`, `pendente`)
 * são mapeados automaticamente para o estado padronizado correspondente.
 */

import {
  RequisicaoSimple,
  ShipmentStatus,
  Stop,
  ActivityLog,
} from '@/shared/types/logistics';

/** Status padronizado de uma requisição. */
export type NormalizedRequisicaoStatus =
  | 'em_fila'
  | 'em_progresso'
  | 'finalizada';

/**
 * Constantes para os 3 estados padronizados de requisição.
 * Use estas constantes ao invés de strings literais para evitar typos.
 */
export const REQUISICAO_STATUS = {
  EM_FILA: 'em_fila',
  EM_PROGRESSO: 'em_progresso',
  FINALIZADA: 'finalizada',
} as const;

/**
 * Normaliza qualquer string de status (incluindo valores legados) para um
 * dos 3 estados padronizados.
 *
 * @param status - Status bruto vindo do banco de dados.
 * @returns Status normalizado: `"em_fila"` | `"em_progresso"` | `"finalizada"`.
 *
 * @example
 * ```ts
 * normalizeRequisicaoStatus("concluida");   // "finalizada"
 * normalizeRequisicaoStatus("separacao");   // "em_progresso"
 * normalizeRequisicaoStatus("pendente");    // "em_fila"
 * normalizeRequisicaoStatus("em_progresso"); // "em_progresso"
 * ```
 */
export const normalizeRequisicaoStatus = (
  status: string,
): NormalizedRequisicaoStatus => {
  const s = (status || '').toLowerCase().trim();
  if (['finalizada', 'concluida', 'aprovada', 'entregue'].includes(s))
    return 'finalizada';
  if (['em_progresso', 'separacao', 'em_separacao'].includes(s))
    return 'em_progresso';
  return 'em_fila';
};

