/**
 * Normaliza variações de nomes de lojas para o valor padronizado (`StoreValue`).
 *
 * @param storeName - Nome da loja em qualquer formato (ex: "Asa Sul", "ASA_SUL", "ASASUL").
 * @returns O valor padronizado correspondente ou `null` se não reconhecido.
 */
// eslint-disable-next-line react-refresh/only-export-components
export const normalizeStoreName = (storeName: string): StoreValue | null => {
  const normalized = storeName.toUpperCase().trim();

  // Mapeamento de variações para valores padronizados
  const storeMapping: Record<string, StoreValue> = {
    FABRICA: 'FABRICA',
    'FÁBRICA': 'FABRICA',
    'MOMMA FABRICA': 'FABRICA',
    'MOMMA FÁBRICA': 'FABRICA',
    'ASA SUL': 'ASA SUL',
    'MOMMA ASA SUL': 'ASA SUL',
    ASASUL: 'ASA SUL',
    ASA_SUL: 'ASA SUL',
    'ASA NORTE': 'ASA NORTE',
    'MOMMA ASA NORTE': 'ASA NORTE',
    ASANORTE: 'ASA NORTE',
    ASA_NORTE: 'ASA NORTE',
    'LAGO SUL': 'LAGO SUL',
    'MOMMA LAGO SUL': 'LAGO SUL',
    LAGOSUL: 'LAGO SUL',
    LAGO_SUL: 'LAGO SUL',
    LAGO: 'LAGO SUL',
    'AGUAS CLARAS': 'AGUAS CLARAS',
    'ÁGUAS CLARAS': 'AGUAS CLARAS',
    'MOMMA AGUAS CLARAS': 'AGUAS CLARAS',
    'MOMMA ÁGUAS CLARAS': 'AGUAS CLARAS',
    AGUAS_CLARAS: 'AGUAS CLARAS',
    AGUASCLARAS: 'AGUAS CLARAS',
    'BRASILIA SHOPPING': 'BRASILIA SHOPPING',
    'BRASÍLIA SHOPPING': 'BRASILIA SHOPPING',
    'MOMMA BRASILIA SHOPPING': 'BRASILIA SHOPPING',
    'MOMMA BRASÍLIA SHOPPING': 'BRASILIA SHOPPING',
    BRASILIA_SHOPPING: 'BRASILIA SHOPPING',
    BRASILIASHOPPING: 'BRASILIA SHOPPING',
  };

  return storeMapping[normalized] || null;
};

/**
 * Retorna o label legível de uma loja a partir do seu valor padronizado.
 *
 * @param value - Valor da loja (ex: `"ASA SUL"`).
 * @returns Label formatado (ex: `"Asa Sul"`) ou o próprio valor se não encontrado.
 */
// eslint-disable-next-line react-refresh/only-export-components
export const getStoreLabel = (value: string): string => {
  const store = STORES.find((s) => s.value === value);
  return store?.label || value;
};

