input.content:
/**
 * Modal de conferência de CHEGADA na loja (espelho da expedição).
 *
 * Quando o caminhão chega na loja destino, o operador entra com a requisição
 * carregada (apenas itens da requisição da própria loja). Para cada item:
 *  - Bipa o QR da caixa → RPC marcar_conferencia_requisicao(uid, requisicaoId, lojaId, meta)
 *    APENAS MARCAÇÃO — não mexe em estoque. Atualiza requisicoes_itens.quantidade_recebida.
 *  - OU marca manual (sem etiqueta): apenas atualiza recebida_via='manual'
 *    + quantidade_recebida = quantidade_solicitada (sem mexer em movimentacoes).
 *
 * Ao clicar "Finalizar e dar entrada": chama dar_entrada_requisicao(requisicaoId) UMA vez,
 * que gera as movimentacoes de estoque de todas as etiquetas bipadas (idempotente).
 *
 * Salva parcial. Operador pode fechar e voltar depois — state hidrata da DB.
 */
import { useEffect, useMemo, useRef, useState } from "react";
import { Dialog, DialogContent, DialogTitle } from "@/shared/ui/dialog";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { ScrollArea } from "@/shared/ui/scroll-area";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from "@/shared/ui/alert-dialog";
import {
  ArrowLeft, Bluetooth, Camera, ScanBarcode, Package, MapPin, CheckCircle2,
  AlertTriangle, Hand, Boxes,
} from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/shared/lib/utils";
import { supabase } from "@/integrations/supabase/client";
import {
  useEtiquetaScanner, playSuccessSound, playErrorSound, playWarningSound,
  type ScannedPayload,
} from "@/shared/hooks/useEtiquetaScanner";
import { CameraScannerStatus } from "@/features/logistica/ui/CameraScannerStatus";

export interface ChegadaItem {
  id: number; // id em requisicoes_itens
  nome_produto: string;
  masterId: number | null;
  quantidade_solicitada: number;
  quantidade_enviada: string; // o que foi expedido pela fábrica
  quantidade_recebida: string; // estado persistido (parcial entre sessões)
  recebida_via: "bip" | "manual" | null;
  recebida_at: string | null;
}

interface BipBuffer {
  itemId: number;
  uid: string;
  qty: number;
  embalagem: string | null;
  bipadoAt: number;
}

interface ManualState {
  open: boolean;
  item?: ChegadaItem;
  quantidade: string;
}

interface Props {
  isOpen: boolean;
  onClose: () => void;
  requisicaoId: number;
  requisicaoNome: string;
  lojaDestinoId: number;
  lojaDestinoNome: string;
  items: ChegadaItem[];
  /** Quando o operador clica em "Finalizar e dar entrada" — pai recarrega/atualiza UI. */
  onConcluida?: () => void;
}

interface DarEntradaResult {
  ok: boolean;
  etiquetas_processadas: number;
  total_quantidade: number;
  ja_processadas: number;
  alertas: string[];
  error?: string;
}

export function RequisicaoChegadaModal({
  isOpen, onClose, requisicaoId, requisicaoNome,
  lojaDestinoId, lojaDestinoNome, items, onConcluida,
}: Props) {
  const [localItems, setLocalItems] = useState<ChegadaItem[]>([]);
  const [bipsLog, setBipsLog] = useState<BipBuffer[]>([]);
  const uidsLidosRef = useRef<Set<string>>(new Set());
  const [manual, setManual] = useState<ManualState>({ open: false, quantidade: "" });
  const [concluindo, setConcluindo] = useState(false);
  const [confirmandoFinalizar, setConfirmandoFinalizar] = useState(false);

  useEffect(() => {
    if (!isOpen) return;
    setLocalItems(items.map((i) => ({ ...i })));
    setBipsLog([]);
    uidsLidosRef.current = new Set();
  }, [isOpen, items]);

  // Marca a flag de chegada_iniciada_at na primeira interação
  const marcarChegadaIniciada = async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    await (supabase.from("requisicoes") as any)
      .update({ chegada_iniciada_at: new Date().toISOString() })
      .eq("id", requisicaoId)
      .is("chegada_iniciada_at", null);
  };

  const updateItemRow = async (
    itemId: number,
    novaQtd: string,
    via: "bip" | "manual",
    userId: string | null,
  ) => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (supabase.from("requisicoes_itens") as any)
      .update({
        quantidade_recebida: novaQtd,
        recebida_via: via,
        recebida_at: new Date().toISOString(),
        recebida_por: userId,
      })
      .eq("id", itemId);
  };

  const handleBip = async (payload: ScannedPayload) => {
    if (!payload.uid) {
      playErrorSound();
      toast.error("Etiqueta sem UID — não rastreável");
      return;
    }
    if (uidsLidosRef.current.has(payload.uid)) {
      playErrorSound();
      toast.error("Caixa já bipada nesta chegada");
      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
      return;
    }

    await marcarChegadaIniciada();

    // Buscar dados da etiqueta para saber produto e quantidade
    const { data: etiquetaData, error: etiquetaErr } = await supabase
      .from("etiquetas_qr")
      .select("quantidade_interna, produto_master_id, lote_id")
      .eq("uid", payload.uid)
      .maybeSingle();

    if (etiquetaErr) {
      playErrorSound();
      toast.error(`Falha ao ler etiqueta: ${etiquetaErr.message}`);
      return;
    }

    const qty = Number(etiquetaData?.quantidade_interna ?? payload.qty ?? 1);
    const masterId = etiquetaData?.produto_master_id ?? null;
    const loteId = (etiquetaData as { lote_id?: string | null } | null)?.lote_id ?? null;

    // RPC de marcação de conferência (NÃO mexe em estoque — só registra o bip)
    // @ts-expect-error RPC nova ainda não regenerada nos tipos
    const { data: marcRes, error: marcErr } = await (supabase.rpc as any)(
      "marcar_conferencia_requisicao",
      {
        p_uid: payload.uid,
        p_requisicao_id: requisicaoId,
        p_loja_id: lojaDestinoId,
        p_meta: {
          quantidade_interna: qty,
          produto_master_id: masterId,
          lote_id: loteId,
        },
      },
    );

    if (marcErr) {
      playErrorSound();
      toast.error(`Falha ao registrar conferência: ${marcErr.message}`);
      return;
    }

    const marcResult = marcRes as { ok: boolean; erro?: string; alertas?: string[] } | null;
    if (!marcResult?.ok) {
      playErrorSound();
      toast.error(marcResult?.erro || "Erro ao registrar bip de conferência");
      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
      return;
    }

    (marcResult.alertas ?? []).forEach((a) => {
      playWarningSound();
      toast.warning(a);
    });

    const target = localItems.find((i) => i.masterId === masterId);
    if (!target) {
      playWarningSound();
      if (navigator.vibrate) navigator.vibrate([100, 50, 100]);
      toast.warning(`Produto #${masterId} NÃO está nesta requisição`);
      uidsLidosRef.current.add(payload.uid);
      return;
    }

    // Soma à quantidade_recebida atual
    const baseAtual = Number(target.quantidade_recebida || "0") || 0;
    const novaQtdNum = baseAtual + qty;

    const { data: { user } } = await supabase.auth.getUser();
    const { error: upErr } = await updateItemRow(target.id, String(novaQtdNum), "bip", user?.id ?? null);
    if (upErr) {
      playErrorSound();
      toast.error(`Erro ao salvar conferência: ${upErr.message}`);
      return;
    }

    playSuccessSound();
    if (navigator.vibrate) navigator.vibrate(80);
    toast.success(`${target.nome_produto} +${qty} un`);

    setLocalItems((prev) =>
      prev.map((i) => i.id === target.id
        ? { ...i, quantidade_recebida: String(novaQtdNum), recebida_via: "bip", recebida_at: new Date().toISOString() }
        : i),
    );
    setBipsLog((prev) => [
      { itemId: target.id, uid: payload.uid, qty, embalagem: null, bipadoAt: Date.now() },
      ...prev,
    ]);
    uidsLidosRef.current.add(payload.uid);
  };

  const scanner = useEtiquetaScanner({
    enabled: isOpen,
    onScan: handleBip,
    cameraElementId: "chegada-qr-reader",
    onInvalid: () => toast.error("QR ilegível"),
    onDuplicate: () => {
      playErrorSound();
      toast.error("Esta etiqueta já foi bipada");
    },
  });

  const askManual = (item: ChegadaItem) => {
    const restante = Math.max(0, item.quantidade_solicitada - (Number(item.quantidade_recebida || "0") || 0));
    setManual({
      open: true,
      item,
      quantidade: String(restante > 0 ? restante : item.quantidade_solicitada),
    });
  };

  const confirmManual = async () => {
    if (!manual.item) return;
    const qty = Number(manual.quantidade);
    if (!Number.isFinite(qty) || qty < 0) {
      toast.error("Quantidade inválida");
      return;
    }
    await marcarChegadaIniciada();
    const { data: { user } } = await supabase.auth.getUser();
    const { error } = await updateItemRow(manual.item.id, String(qty), "manual", user?.id ?? null);
    if (error) {
      toast.error(`Erro ao salvar: ${error.message}`);
      return;
    }
    setLocalItems((prev) =>
      prev.map((i) => i.id === manual.item!.id
        ? { ...i, quantidade_recebida: String(qty), recebida_via: "manual", recebida_at: new Date().toISOString() }
        : i),
    );
    setManual({ open: false, quantidade: "" });
    toast.success(`${manual.item.nome_produto}: ${qty} un (manual)`);
  };

  const executarFinalizacao = async () => {
    setConcluindo(true);
    setConfirmandoFinalizar(false);

    // Chamar dar_entrada_requisicao UMA vez — dá entrada no estoque de TODAS as etiquetas bipadas
    // @ts-expect-error RPC nova ainda não regenerada nos tipos
    const { data: entradaRes, error: entradaErr } = await (supabase.rpc as any)(
      "dar_entrada_requisicao",
      { p_requisicao_id: requisicaoId },
    );

    if (entradaErr) {
      toast.error(`Erro ao dar entrada no estoque: ${entradaErr.message}`);
      setConcluindo(false);
      return;
    }

    const resultado = entradaRes as DarEntradaResult | null;
    if (!resultado?.ok) {
      toast.error(resultado?.error || "Falha ao registrar entrada no estoque");
      setConcluindo(false);
      return;
    }

    // Feedback de sucesso
    toast.success(
      `Entrada registrada: ${resultado.etiquetas_processadas} etiqueta(s), ${resultado.total_quantidade} unidade(s)`,
    );

    if (resultado.ja_processadas > 0) {
      toast.info(`${resultado.ja_processadas} etiqueta(s) já haviam sido processadas anteriormente`);
    }

    (resultado.alertas ?? []).forEach((a) => toast.warning(a));

    // Marcar chegada como concluída no banco
    const { data: { user } } = await supabase.auth.getUser();
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    await (supabase.from("requisicoes") as any)
      .update({
        chegada_concluida_at: new Date().toISOString(),
        chegada_concluida_por: user?.id ?? null,
      })
      .eq("id", requisicaoId);

    setConcluindo(false);
    onConcluida?.();
    onClose();
  };

  const finalizarEDarEntrada = () => {
    // Se há itens sem conferência, pedir confirmação antes de finalizar parcialmente
    if (stats.conferidos < stats.totalItens) {
      setConfirmandoFinalizar(true);
      return;
    }
    void executarFinalizacao();
  };

  const stats = useMemo(() => {
    const totalItens = localItems.length;
    const conferidos = localItems.filter((i) => (Number(i.quantidade_recebida || "0") || 0) > 0).length;
    const totalSolicitado = localItems.reduce((acc, i) => acc + (i.quantidade_solicitada || 0), 0);
    const totalRecebido = localItems.reduce((acc, i) => acc + (Number(i.quantidade_recebida || "0") || 0), 0);
    const caixasBipadas = bipsLog.length;
    const allConferidos = totalItens > 0 && conferidos === totalItens;
    return { totalItens, conferidos, totalSolicitado, totalRecebido, caixasBipadas, allConferidos };
  }, [localItems, bipsLog]);

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent
        data-mia-modal="conferir-chegada-requisicao-nome"
        className="max-w-[100vw] sm:max-w-[98vw] w-full h-[100dvh] sm:h-[95vh] p-0 flex flex-col overflow-hidden bg-white dark:bg-[#0A0A0A] sm:rounded-[1.5rem] rounded-none"
      >
        {/* Header */}
        <div className="flex items-center justify-between gap-2 px-3 sm:px-5 py-2 sm:py-3 flex-shrink-0 border-b border-[#57715B]/10">
          <div className="flex items-center gap-2 sm:gap-3 min-w-0 flex-1">
            <Button
              data-mia-action="close"
              variant="ghost"
              size="icon"
              onClick={onClose}
              className="rounded-2xl hover:bg-[#57715B]/10 h-11 w-11 flex-shrink-0"
            >
              <ArrowLeft className="w-5 h-5 text-[#57715B]" />
            </Button>
            <div className="h-10 w-10 rounded-2xl bg-[#57715B]/10 flex items-center justify-center flex-shrink-0">
              <ScanBarcode className="h-5 w-5 text-[#57715B]" />
            </div>
            <div className="min-w-0 flex-1">
              <DialogTitle className="text-base sm:text-lg font-bold text-[#57715B] dark:text-[#8FAE94] truncate">
                Conferir chegada · {requisicaoNome}
              </DialogTitle>
              <p className="text-[11px] sm:text-xs text-muted-foreground flex items-center gap-1 truncate">
                <MapPin className="w-3 h-3 flex-shrink-0" /> <span className="truncate">{lojaDestinoNome}</span>
              </p>
            </div>
          </div>
          <div className="flex p-1 rounded-xl bg-white/60 dark:bg-zinc-800 border border-white/20 dark:border-white/10 flex-shrink-0">
            <button
              onClick={() => scanner.setScanMode("bluetooth")}
              aria-label="Scanner Bluetooth"
              className={cn(
                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
                scanner.scanMode === "bluetooth"
                  ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm"
                  : "text-muted-foreground hover:text-foreground",
              )}
            >
              <Bluetooth className="h-4 w-4" /> <span className="hidden sm:inline">Scanner</span>
            </button>
            <button
              onClick={() => scanner.setScanMode("camera")}
              aria-label="Scanner por câmera"
              className={cn(
                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
                scanner.scanMode === "camera"
                  ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm"
                  : "text-muted-foreground hover:text-foreground",
              )}
            >
              <Camera className="h-4 w-4" /> <span className="hidden sm:inline">Câmera</span>
            </button>
          </div>
        </div>

        {/* Stats */}
        <div className="px-3 sm:px-5 py-3 flex-shrink-0 border-b border-[#57715B]/10 grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-3">
          <Stat label="Itens conferidos" value={`${stats.conferidos}/${stats.totalItens}`} />
          <Stat label="Caixas bipadas" value={String(stats.caixasBipadas)} icon={<Boxes className="w-3 h-3" />} />
          <Stat label="Un. recebidas" value={`${stats.totalRecebido}/${stats.totalSolicitado}`} />
          <Stat label="Bips" value={String(stats.caixasBipadas)} />
        </div>

        {/* Scanner input invisível */}
        {scanner.scanMode === "bluetooth" && <input {...scanner.inputProps} />}

        {/* Body */}
        <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
          {scanner.scanMode === "camera" ? (
            <div className="w-full md:w-[260px] flex-shrink-0 border-b md:border-b-0 md:border-r border-[#57715B]/10 bg-black overflow-hidden relative">
              <div id={scanner.cameraElementId} className="w-full h-[200px] md:h-full" />
              <CameraScannerStatus
                starting={scanner.cameraStarting}
                error={scanner.cameraError}
                onRetry={scanner.retryCamera}
              />
            </div>
          ) : (
            <div
              className="w-full md:w-[200px] flex-shrink-0 border-b md:border-b-0 md:border-r border-[#57715B]/10 flex flex-col items-center justify-center p-5 cursor-pointer"
              onClick={() => document.querySelector<HTMLInputElement>("input[autofocus]")?.focus()}
            >
              <div className="w-20 h-20 rounded-full bg-[#57715B]/10 flex items-center justify-center relative">
                <Bluetooth className="w-9 h-9 text-[#57715B]" />
                <div
                  className="absolute inset-0 rounded-full border-[3px] border-[#57715B]/20 border-t-[#57715B] animate-spin"
                  style={{ animationDuration: "3s" }}
                />
              </div>
              <h3 className="text-sm font-bold text-[#57715B] dark:text-[#8FAE94] mt-4">Aguardando bip…</h3>
              <p className="text-[11px] text-muted-foreground text-center mt-1">
                Sem etiqueta? Marque manual no item.
              </p>
            </div>
          )}

          {/* Lista de itens da requisição */}
          <div className="flex-1 flex flex-col overflow-hidden">
            <ScrollArea className="flex-1">
              <div className="p-2.5 space-y-2">
                {localItems.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-16 text-muted-foreground/40">
                    <Package className="w-12 h-12 mb-2" />
                    <p className="text-sm font-semibold">Sem itens nessa requisição</p>
                  </div>
                ) : (
                  localItems.map((item) => (
                    <ItemRow key={item.id} item={item} onMarcarManual={() => askManual(item)} />
                  ))
                )}
              </div>
            </ScrollArea>
          </div>
        </div>

        {/* Footer */}
        <div
          className="px-3 sm:px-5 py-3 border-t border-[#57715B]/10 flex items-center justify-between gap-2 flex-shrink-0"
          style={{ paddingBottom: "calc(env(safe-area-inset-bottom) + 12px)" }}
        >
          <p className="text-[11px] sm:text-xs text-muted-foreground truncate">
            {stats.allConferidos
              ? "Todos os itens conferidos."
              : `${stats.totalItens - stats.conferidos} item(ns) pendente(s).`}
          </p>
          <div className="flex gap-2 flex-shrink-0">
            <Button
              data-mia-action="close"
              onClick={onClose}
              variant="outline"
              className="h-11 border-[#57715B]/20 hover:bg-[#57715B]/10"
            >
              Salvar e fechar
            </Button>
            <Button
              data-mia-action="finalizar-dar-entrada"
              onClick={finalizarEDarEntrada}
              disabled={concluindo}
              className={cn(
                "h-11",
                stats.allConferidos
                  ? "bg-emerald-600 hover:bg-emerald-700"
                  : "bg-[#57715B] hover:bg-[#465b49]",
                "text-white",
              )}
            >
              {concluindo ? "Finalizando…" : "Finalizar e dar entrada"}
            </Button>
          </div>
        </div>
      </DialogContent>

      {/* Confirmação de finalização parcial */}
      <AlertDialog
        open={confirmandoFinalizar}
        onOpenChange={(open) => !open && setConfirmandoFinalizar(false)}
      >
        <AlertDialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
          <AlertDialogHeader>
            <AlertDialogTitle className="flex items-center gap-2">
              <AlertTriangle className="w-5 h-5 text-amber-600" />
              Finalizar parcialmente?
            </AlertDialogTitle>
            <AlertDialogDescription asChild>
              <div className="text-sm text-muted-foreground space-y-2">
                <p>
                  <strong className="text-foreground">
                    {stats.totalItens - stats.conferidos} item(ns)
                  </strong>{" "}
                  ainda não foram bipados.
                </p>
                <p>
                  O estoque será dado entrada apenas nas etiquetas bipadas (
                  {stats.caixasBipadas} caixa(s)). Os itens não conferidos ficam pendentes.
                </p>
              </div>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel
              onClick={() => setConfirmandoFinalizar(false)}
              className="border-[#57715B]/20 hover:bg-[#57715B]/10"
            >
              Voltar e bipar
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={() => void executarFinalizacao()}
              className="bg-[#57715B] hover:bg-[#465b49] text-white"
            >
              Finalizar mesmo assim
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Manual entry */}
      <AlertDialog
        open={manual.open}
        onOpenChange={(open) => !open && setManual((s) => ({ ...s, open: false }))}
      >
        <AlertDialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
          <AlertDialogHeader>
            <AlertDialogTitle className="flex items-center gap-2">
              <Hand className="w-5 h-5" /> Marcar manual
            </AlertDialogTitle>
            <AlertDialogDescription asChild>
              <div className="space-y-3 pt-2">
                <p className="font-semibold text-foreground">{manual.item?.nome_produto}</p>
                <p className="text-xs text-muted-foreground">
                  Pedido: {manual.item?.quantidade_solicitada} un · Já recebido:{" "}
                  {manual.item?.quantidade_recebida || 0} un
                </p>
                <div>
                  <label className="text-xs uppercase tracking-wider font-bold text-muted-foreground block mb-1">
                    Quantidade recebida (un)
                  </label>
                  <Input
                    type="number"
                    min="0"
                    step="any"
                    value={manual.quantidade}
                    onChange={(e) => setManual((s) => ({ ...s, quantidade: e.target.value }))}
                    autoFocus
                    className="h-11 text-lg font-bold bg-white/60 dark:bg-black/20 border-[#57715B]/20 focus-visible:ring-[#57715B]/30"
                  />
                </div>
                <p className="text-xs text-amber-700 bg-amber-50 dark:bg-amber-900/20 rounded-md p-2">
                  Marcar manual NÃO gera movimentação de estoque automática (sem etiqueta = sem
                  rastreabilidade).
                </p>
              </div>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel
              onClick={() => setManual((s) => ({ ...s, open: false }))}
              className="border-[#57715B]/20 hover:bg-[#57715B]/10"
            >
              Cancelar
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={() => void confirmManual()}
              className="bg-[#57715B] hover:bg-[#465b49] text-white"
            >
              Confirmar
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </Dialog>
  );
}

function Stat({
  label,
  value,
  icon,
}: {
  label: string;
  value: string | number;
  icon?: React.ReactNode;
}) {
  return (
    <div className="text-center min-w-0">
      <p className="text-[9px] sm:text-[10px] uppercase tracking-widest text-muted-foreground font-bold truncate flex items-center gap-1 justify-center">
        {icon}
        {label}
      </p>
      <p className="text-xl sm:text-2xl font-black tabular-nums text-[#57715B]">{value}</p>
    </div>
  );
}

function ItemRow({
  item,
  onMarcarManual,
}: {
  item: ChegadaItem;
  onMarcarManual: () => void;
}) {
  const recebido = Number(item.quantidade_recebida || "0") || 0;
  const solicitado = item.quantidade_solicitada || 0;
  const enviado = Number(item.quantidade_enviada || "0") || 0;
  const pct = solicitado > 0 ? Math.min(100, Math.round((recebido / solicitado) * 100)) : 0;
  const status: "vazio" | "parcial" | "completo" | "excesso" =
    recebido === 0
      ? "vazio"
      : recebido > solicitado
        ? "excesso"
        : recebido >= solicitado
          ? "completo"
          : "parcial";
  const ring =
    status === "completo"
      ? "border-emerald-500/40 bg-emerald-500/5"
      : status === "excesso"
        ? "border-amber-500/40 bg-amber-500/5"
        : status === "parcial"
          ? "border-[#57715B]/30 bg-[#57715B]/5"
          : "border-white/30 dark:border-white/10";
  const bg =
    status === "completo"
      ? "bg-emerald-500"
      : status === "excesso"
        ? "bg-amber-500"
        : status === "parcial"
          ? "bg-[#57715B]"
          : "bg-zinc-300 dark:bg-zinc-700";
  return (
    <div className={cn("rounded-xl border-2 p-3", ring)}>
      <div className="flex items-start justify-between gap-2 mb-1.5">
        <div className="min-w-0 flex-1">
          <p className="text-sm font-semibold leading-tight truncate flex items-center gap-2">
            {status === "completo" && (
              <CheckCircle2 className="w-4 h-4 text-emerald-600 flex-shrink-0" />
            )}
            {status === "excesso" && (
              <AlertTriangle className="w-4 h-4 text-amber-600 flex-shrink-0" />
            )}
            <span className="truncate">{item.nome_produto}</span>
          </p>
          <p className="text-[11px] text-muted-foreground mt-0.5">
            Pedido <b>{solicitado}</b> un · Expedido <b>{enviado || 0}</b> un
            {item.recebida_via && (
              <span
                className={cn(
                  "ml-2 inline-block px-1.5 py-0.5 rounded text-[9px] font-bold uppercase tracking-wider",
                  item.recebida_via === "bip"
                    ? "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-300"
                    : "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-300",
                )}
              >
                {item.recebida_via}
              </span>
            )}
          </p>
        </div>
        <div className="flex items-center gap-2 flex-shrink-0">
          <span
            className={cn(
              "text-sm font-bold tabular-nums",
              status === "completo"
                ? "text-emerald-700"
                : status === "excesso"
                  ? "text-amber-700"
                  : "text-foreground",
            )}
          >
            {recebido}/{solicitado}
          </span>
          <Button
            data-mia-action="marcar-manual"
            size="sm"
            variant="outline"
            className="h-8 gap-1 text-[11px] border-[#57715B]/20 hover:bg-[#57715B]/10"
            onClick={onMarcarManual}
          >
            <Hand className="w-3 h-3" /> Manual
          </Button>
        </div>
      </div>
      <div className="w-full h-1.5 bg-zinc-100 dark:bg-zinc-800 rounded-full overflow-hidden">
        <div
          className={cn("h-full rounded-full transition-all duration-500", bg)}
          style={{ width: `${pct}%` }}
        />
      </div>
    </div>
  );
}

toolUseResult.content:
/**
 * Modal de conferência de CHEGADA na loja (espelho da expedição).
 *
 * Quando o caminhão chega na loja destino, o operador entra com a requisição
 * carregada (apenas itens da requisição da própria loja). Para cada item:
 *  - Bipa o QR da caixa → RPC marcar_conferencia_requisicao(uid, requisicaoId, lojaId, meta)
 *    APENAS MARCAÇÃO — não mexe em estoque. Atualiza requisicoes_itens.quantidade_recebida.
 *  - OU marca manual (sem etiqueta): apenas atualiza recebida_via='manual'
 *    + quantidade_recebida = quantidade_solicitada (sem mexer em movimentacoes).
 *
 * Ao clicar "Finalizar e dar entrada": chama dar_entrada_requisicao(requisicaoId) UMA vez,
 * que gera as movimentacoes de estoque de todas as etiquetas bipadas (idempotente).
 *
 * Salva parcial. Operador pode fechar e voltar depois — state hidrata da DB.
 */
import { useEffect, useMemo, useRef, useState } from "react";
import { Dialog, DialogContent, DialogTitle } from "@/shared/ui/dialog";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { ScrollArea } from "@/shared/ui/scroll-area";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from "@/shared/ui/alert-dialog";
import {
  ArrowLeft, Bluetooth, Camera, ScanBarcode, Package, MapPin, CheckCircle2,
  AlertTriangle, Hand, Boxes,
} from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/shared/lib/utils";
import { supabase } from "@/integrations/supabase/client";
import {
  useEtiquetaScanner, playSuccessSound, playErrorSound, playWarningSound,
  type ScannedPayload,
} from "@/shared/hooks/useEtiquetaScanner";
import { CameraScannerStatus } from "@/features/logistica/ui/CameraScannerStatus";

export interface ChegadaItem {
  id: number; // id em requisicoes_itens
  nome_produto: string;
  masterId: number | null;
  quantidade_solicitada: number;
  quantidade_enviada: string; // o que foi expedido pela fábrica
  quantidade_recebida: string; // estado persistido (parcial entre sessões)
  recebida_via: "bip" | "manual" | null;
  recebida_at: string | null;
}

interface BipBuffer {
  itemId: number;
  uid: string;
  qty: number;
  embalagem: string | null;
  bipadoAt: number;
}

interface ManualState {
  open: boolean;
  item?: ChegadaItem;
  quantidade: string;
}

interface Props {
  isOpen: boolean;
  onClose: () => void;
  requisicaoId: number;
  requisicaoNome: string;
  lojaDestinoId: number;
  lojaDestinoNome: string;
  items: ChegadaItem[];
  /** Quando o operador clica em "Finalizar e dar entrada" — pai recarrega/atualiza UI. */
  onConcluida?: () => void;
}

interface DarEntradaResult {
  ok: boolean;
  etiquetas_processadas: number;
  total_quantidade: number;
  ja_processadas: number;
  alertas: string[];
  error?: string;
}

export function RequisicaoChegadaModal({
  isOpen, onClose, requisicaoId, requisicaoNome,
  lojaDestinoId, lojaDestinoNome, items, onConcluida,
}: Props) {
  const [localItems, setLocalItems] = useState<ChegadaItem[]>([]);
  const [bipsLog, setBipsLog] = useState<BipBuffer[]>([]);
  const uidsLidosRef = useRef<Set<string>>(new Set());
  const [manual, setManual] = useState<ManualState>({ open: false, quantidade: "" });
  const [concluindo, setConcluindo] = useState(false);
  const [confirmandoFinalizar, setConfirmandoFinalizar] = useState(false);

  useEffect(() => {
    if (!isOpen) return;
    setLocalItems(items.map((i) => ({ ...i })));
    setBipsLog([]);
    uidsLidosRef.current = new Set();
  }, [isOpen, items]);

  // Marca a flag de chegada_iniciada_at na primeira interação
  const marcarChegadaIniciada = async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    await (supabase.from("requisicoes") as any)
      .update({ chegada_iniciada_at: new Date().toISOString() })
      .eq("id", requisicaoId)
      .is("chegada_iniciada_at", null);
  };

  const updateItemRow = async (
    itemId: number,
    novaQtd: string,
    via: "bip" | "manual",
    userId: string | null,
  ) => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (supabase.from("requisicoes_itens") as any)
      .update({
        quantidade_recebida: novaQtd,
        recebida_via: via,
        recebida_at: new Date().toISOString(),
        recebida_por: userId,
      })
      .eq("id", itemId);
  };

  const handleBip = async (payload: ScannedPayload) => {
    if (!payload.uid) {
      playErrorSound();
      toast.error("Etiqueta sem UID — não rastreável");
      return;
    }
    if (uidsLidosRef.current.has(payload.uid)) {
      playErrorSound();
      toast.error("Caixa já bipada nesta chegada");
      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
      return;
    }

    await marcarChegadaIniciada();

    // Buscar dados da etiqueta para saber produto e quantidade
    const { data: etiquetaData, error: etiquetaErr } = await supabase
      .from("etiquetas_qr")
      .select("quantidade_interna, produto_master_id, lote_id")
      .eq("uid", payload.uid)
      .maybeSingle();

    if (etiquetaErr) {
      playErrorSound();
      toast.error(`Falha ao ler etiqueta: ${etiquetaErr.message}`);
      return;
    }

    const qty = Number(etiquetaData?.quantidade_interna ?? payload.qty ?? 1);
    const masterId = etiquetaData?.produto_master_id ?? null;
    const loteId = (etiquetaData as { lote_id?: string | null } | null)?.lote_id ?? null;

    // RPC de marcação de conferência (NÃO mexe em estoque — só registra o bip)
    // @ts-expect-error RPC nova ainda não regenerada nos tipos
    const { data: marcRes, error: marcErr } = await (supabase.rpc as any)(
      "marcar_conferencia_requisicao",
      {
        p_uid: payload.uid,
        p_requisicao_id: requisicaoId,
        p_loja_id: lojaDestinoId,
        p_meta: {
          quantidade_interna: qty,
          produto_master_id: masterId,
          lote_id: loteId,
        },
      },
    );

    if (marcErr) {
      playErrorSound();
      toast.error(`Falha ao registrar conferência: ${marcErr.message}`);
      return;
    }

    const marcResult = marcRes as { ok: boolean; erro?: string; alertas?: string[] } | null;
    if (!marcResult?.ok) {
      playErrorSound();
      toast.error(marcResult?.erro || "Erro ao registrar bip de conferência");
      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
      return;
    }

    (marcResult.alertas ?? []).forEach((a) => {
      playWarningSound();
      toast.warning(a);
    });

    const target = localItems.find((i) => i.masterId === masterId);
    if (!target) {
      playWarningSound();
      if (navigator.vibrate) navigator.vibrate([100, 50, 100]);
      toast.warning(`Produto #${masterId} NÃO está nesta requisição`);
      uidsLidosRef.current.add(payload.uid);
      return;
    }

    // Soma à quantidade_recebida atual
    const baseAtual = Number(target.quantidade_recebida || "0") || 0;
    const novaQtdNum = baseAtual + qty;

    const { data: { user } } = await supabase.auth.getUser();
    const { error: upErr } = await updateItemRow(target.id, String(novaQtdNum), "bip", user?.id ?? null);
    if (upErr) {
      playErrorSound();
      toast.error(`Erro ao salvar conferência: ${upErr.message}`);
      return;
    }

    playSuccessSound();
    if (navigator.vibrate) navigator.vibrate(80);
    toast.success(`${target.nome_produto} +${qty} un`);

    setLocalItems((prev) =>
      prev.map((i) => i.id === target.id
        ? { ...i, quantidade_recebida: String(novaQtdNum), recebida_via: "bip", recebida_at: new Date().toISOString() }
        : i),
    );
    setBipsLog((prev) => [
      { itemId: target.id, uid: payload.uid, qty, embalagem: null, bipadoAt: Date.now() },
      ...prev,
    ]);
    uidsLidosRef.current.add(payload.uid);
  };

  const scanner = useEtiquetaScanner({
    enabled: isOpen,
    onScan: handleBip,
    cameraElementId: "chegada-qr-reader",
    onInvalid: () => toast.error("QR ilegível"),
    onDuplicate: () => {
      playErrorSound();
      toast.error("Esta etiqueta já foi bipada");
    },
  });

  const askManual = (item: ChegadaItem) => {
    const restante = Math.max(0, item.quantidade_solicitada - (Number(item.quantidade_recebida || "0") || 0));
    setManual({
      open: true,
      item,
      quantidade: String(restante > 0 ? restante : item.quantidade_solicitada),
    });
  };

  const confirmManual = async () => {
    if (!manual.item) return;
    const qty = Number(manual.quantidade);
    if (!Number.isFinite(qty) || qty < 0) {
      toast.error("Quantidade inválida");
      return;
    }
    await marcarChegadaIniciada();
    const { data: { user } } = await supabase.auth.getUser();
    const { error } = await updateItemRow(manual.item.id, String(qty), "manual", user?.id ?? null);
    if (error) {
      toast.error(`Erro ao salvar: ${error.message}`);
      return;
    }
    setLocalItems((prev) =>
      prev.map((i) => i.id === manual.item!.id
        ? { ...i, quantidade_recebida: String(qty), recebida_via: "manual", recebida_at: new Date().toISOString() }
        : i),
    );
    setManual({ open: false, quantidade: "" });
    toast.success(`${manual.item.nome_produto}: ${qty} un (manual)`);
  };

  const executarFinalizacao = async () => {
    setConcluindo(true);
    setConfirmandoFinalizar(false);

    // Chamar dar_entrada_requisicao UMA vez — dá entrada no estoque de TODAS as etiquetas bipadas
    // @ts-expect-error RPC nova ainda não regenerada nos tipos
    const { data: entradaRes, error: entradaErr } = await (supabase.rpc as any)(
      "dar_entrada_requisicao",
      { p_requisicao_id: requisicaoId },
    );

    if (entradaErr) {
      toast.error(`Erro ao dar entrada no estoque: ${entradaErr.message}`);
      setConcluindo(false);
      return;
    }

    const resultado = entradaRes as DarEntradaResult | null;
    if (!resultado?.ok) {
      toast.error(resultado?.error || "Falha ao registrar entrada no estoque");
      setConcluindo(false);
      return;
    }

    // Feedback de sucesso
    toast.success(
      `Entrada registrada: ${resultado.etiquetas_processadas} etiqueta(s), ${resultado.total_quantidade} unidade(s)`,
    );

    if (resultado.ja_processadas > 0) {
      toast.info(`${resultado.ja_processadas} etiqueta(s) já haviam sido processadas anteriormente`);
    }

    (resultado.alertas ?? []).forEach((a) => toast.warning(a));

    // Marcar chegada como concluída no banco
    const { data: { user } } = await supabase.auth.getUser();
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    await (supabase.from("requisicoes") as any)
      .update({
        chegada_concluida_at: new Date().toISOString(),
        chegada_concluida_por: user?.id ?? null,
      })
      .eq("id", requisicaoId);

    setConcluindo(false);
    onConcluida?.();
    onClose();
  };

  const finalizarEDarEntrada = () => {
    // Se há itens sem conferência, pedir confirmação antes de finalizar parcialmente
    if (stats.conferidos < stats.totalItens) {
      setConfirmandoFinalizar(true);
      return;
    }
    void executarFinalizacao();
  };

  const stats = useMemo(() => {
    const totalItens = localItems.length;
    const conferidos = localItems.filter((i) => (Number(i.quantidade_recebida || "0") || 0) > 0).length;
    const totalSolicitado = localItems.reduce((acc, i) => acc + (i.quantidade_solicitada || 0), 0);
    const totalRecebido = localItems.reduce((acc, i) => acc + (Number(i.quantidade_recebida || "0") || 0), 0);
    const caixasBipadas = bipsLog.length;
    const allConferidos = totalItens > 0 && conferidos === totalItens;
    return { totalItens, conferidos, totalSolicitado, totalRecebido, caixasBipadas, allConferidos };
  }, [localItems, bipsLog]);

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent
        data-mia-modal="conferir-chegada-requisicao-nome"
        className="max-w-[100vw] sm:max-w-[98vw] w-full h-[100dvh] sm:h-[95vh] p-0 flex flex-col overflow-hidden bg-white dark:bg-[#0A0A0A] sm:rounded-[1.5rem] rounded-none"
      >
        {/* Header */}
        <div className="flex items-center justify-between gap-2 px-3 sm:px-5 py-2 sm:py-3 flex-shrink-0 border-b border-[#57715B]/10">
          <div className="flex items-center gap-2 sm:gap-3 min-w-0 flex-1">
            <Button
              data-mia-action="close"
              variant="ghost"
              size="icon"
              onClick={onClose}
              className="rounded-2xl hover:bg-[#57715B]/10 h-11 w-11 flex-shrink-0"
            >
              <ArrowLeft className="w-5 h-5 text-[#57715B]" />
            </Button>
            <div className="h-10 w-10 rounded-2xl bg-[#57715B]/10 flex items-center justify-center flex-shrink-0">
              <ScanBarcode className="h-5 w-5 text-[#57715B]" />
            </div>
            <div className="min-w-0 flex-1">
              <DialogTitle className="text-base sm:text-lg font-bold text-[#57715B] dark:text-[#8FAE94] truncate">
                Conferir chegada · {requisicaoNome}
              </DialogTitle>
              <p className="text-[11px] sm:text-xs text-muted-foreground flex items-center gap-1 truncate">
                <MapPin className="w-3 h-3 flex-shrink-0" /> <span className="truncate">{lojaDestinoNome}</span>
              </p>
            </div>
          </div>
          <div className="flex p-1 rounded-xl bg-white/60 dark:bg-zinc-800 border border-white/20 dark:border-white/10 flex-shrink-0">
            <button
              onClick={() => scanner.setScanMode("bluetooth")}
              aria-label="Scanner Bluetooth"
              className={cn(
                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
                scanner.scanMode === "bluetooth"
                  ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm"
                  : "text-muted-foreground hover:text-foreground",
              )}
            >
              <Bluetooth className="h-4 w-4" /> <span className="hidden sm:inline">Scanner</span>
            </button>
            <button
              onClick={() => scanner.setScanMode("camera")}
              aria-label="Scanner por câmera"
              className={cn(
                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
                scanner.scanMode === "camera"
                  ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm"
                  : "text-muted-foreground hover:text-foreground",
              )}
            >
              <Camera className="h-4 w-4" /> <span className="hidden sm:inline">Câmera</span>
            </button>
          </div>
        </div>

        {/* Stats */}
        <div className="px-3 sm:px-5 py-3 flex-shrink-0 border-b border-[#57715B]/10 grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-3">
          <Stat label="Itens conferidos" value={`${stats.conferidos}/${stats.totalItens}`} />
          <Stat label="Caixas bipadas" value={String(stats.caixasBipadas)} icon={<Boxes className="w-3 h-3" />} />
          <Stat label="Un. recebidas" value={`${stats.totalRecebido}/${stats.totalSolicitado}`} />
          <Stat label="Bips" value={String(stats.caixasBipadas)} />
        </div>

        {/* Scanner input invisível */}
        {scanner.scanMode === "bluetooth" && <input {...scanner.inputProps} />}

        {/* Body */}
        <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
          {scanner.scanMode === "camera" ? (
            <div className="w-full md:w-[260px] flex-shrink-0 border-b md:border-b-0 md:border-r border-[#57715B]/10 bg-black overflow-hidden relative">
              <div id={scanner.cameraElementId} className="w-full h-[200px] md:h-full" />
              <CameraScannerStatus
                starting={scanner.cameraStarting}
                error={scanner.cameraError}
                onRetry={scanner.retryCamera}
              />
            </div>
          ) : (
            <div
              className="w-full md:w-[200px] flex-shrink-0 border-b md:border-b-0 md:border-r border-[#57715B]/10 flex flex-col items-center justify-center p-5 cursor-pointer"
              onClick={() => document.querySelector<HTMLInputElement>("input[autofocus]")?.focus()}
            >
              <div className="w-20 h-20 rounded-full bg-[#57715B]/10 flex items-center justify-center relative">
                <Bluetooth className="w-9 h-9 text-[#57715B]" />
                <div
                  className="absolute inset-0 rounded-full border-[3px] border-[#57715B]/20 border-t-[#57715B] animate-spin"
                  style={{ animationDuration: "3s" }}
                />
              </div>
              <h3 className="text-sm font-bold text-[#57715B] dark:text-[#8FAE94] mt-4">Aguardando bip…</h3>
              <p className="text-[11px] text-muted-foreground text-center mt-1">
                Sem etiqueta? Marque manual no item.
              </p>
            </div>
          )}

          {/* Lista de itens da requisição */}
          <div className="flex-1 flex flex-col overflow-hidden">
            <ScrollArea className="flex-1">
              <div className="p-2.5 space-y-2">
                {localItems.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-16 text-muted-foreground/40">
                    <Package className="w-12 h-12 mb-2" />
                    <p className="text-sm font-semibold">Sem itens nessa requisição</p>
                  </div>
                ) : (
                  localItems.map((item) => (
                    <ItemRow key={item.id} item={item} onMarcarManual={() => askManual(item)} />
                  ))
                )}
              </div>
            </ScrollArea>
          </div>
        </div>

        {/* Footer */}
        <div
          className="px-3 sm:px-5 py-3 border-t border-[#57715B]/10 flex items-center justify-between gap-2 flex-shrink-0"
          style={{ paddingBottom: "calc(env(safe-area-inset-bottom) + 12px)" }}
        >
          <p className="text-[11px] sm:text-xs text-muted-foreground truncate">
            {stats.allConferidos
              ? "Todos os itens conferidos."
              : `${stats.totalItens - stats.conferidos} item(ns) pendente(s).`}
          </p>
          <div className="flex gap-2 flex-shrink-0">
            <Button
              data-mia-action="close"
              onClick={onClose}
              variant="outline"
              className="h-11 border-[#57715B]/20 hover:bg-[#57715B]/10"
            >
              Salvar e fechar
            </Button>
            <Button
              data-mia-action="finalizar-dar-entrada"
              onClick={finalizarEDarEntrada}
              disabled={concluindo}
              className={cn(
                "h-11",
                stats.allConferidos
                  ? "bg-emerald-600 hover:bg-emerald-700"
                  : "bg-[#57715B] hover:bg-[#465b49]",
                "text-white",
              )}
            >
              {concluindo ? "Finalizando…" : "Finalizar e dar entrada"}
            </Button>
          </div>
        </div>
      </DialogContent>

      {/* Confirmação de finalização parcial */}
      <AlertDialog
        open={confirmandoFinalizar}
        onOpenChange={(open) => !open && setConfirmandoFinalizar(false)}
      >
        <AlertDialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
          <AlertDialogHeader>
            <AlertDialogTitle className="flex items-center gap-2">
              <AlertTriangle className="w-5 h-5 text-amber-600" />
              Finalizar parcialmente?
            </AlertDialogTitle>
            <AlertDialogDescription asChild>
              <div className="text-sm text-muted-foreground space-y-2">
                <p>
                  <strong className="text-foreground">
                    {stats.totalItens - stats.conferidos} item(ns)
                  </strong>{" "}
                  ainda não foram bipados.
                </p>
                <p>
                  O estoque será dado entrada apenas nas etiquetas bipadas (
                  {stats.caixasBipadas} caixa(s)). Os itens não conferidos ficam pendentes.
                </p>
              </div>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel
              onClick={() => setConfirmandoFinalizar(false)}
              className="border-[#57715B]/20 hover:bg-[#57715B]/10"
            >
              Voltar e bipar
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={() => void executarFinalizacao()}
              className="bg-[#57715B] hover:bg-[#465b49] text-white"
            >
              Finalizar mesmo assim
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Manual entry */}
      <AlertDialog
        open={manual.open}
        onOpenChange={(open) => !open && setManual((s) => ({ ...s, open: false }))}
      >
        <AlertDialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
          <AlertDialogHeader>
            <AlertDialogTitle className="flex items-center gap-2">
              <Hand className="w-5 h-5" /> Marcar manual
            </AlertDialogTitle>
            <AlertDialogDescription asChild>
              <div className="space-y-3 pt-2">
                <p className="font-semibold text-foreground">{manual.item?.nome_produto}</p>
                <p className="text-xs text-muted-foreground">
                  Pedido: {manual.item?.quantidade_solicitada} un · Já recebido:{" "}
                  {manual.item?.quantidade_recebida || 0} un
                </p>
                <div>
                  <label className="text-xs uppercase tracking-wider font-bold text-muted-foreground block mb-1">
                    Quantidade recebida (un)
                  </label>
                  <Input
                    type="number"
                    min="0"
                    step="any"
                    value={manual.quantidade}
                    onChange={(e) => setManual((s) => ({ ...s, quantidade: e.target.value }))}
                    autoFocus
                    className="h-11 text-lg font-bold bg-white/60 dark:bg-black/20 border-[#57715B]/20 focus-visible:ring-[#57715B]/30"
                  />
                </div>
                <p className="text-xs text-amber-700 bg-amber-50 dark:bg-amber-900/20 rounded-md p-2">
                  Marcar manual NÃO gera movimentação de estoque automática (sem etiqueta = sem
                  rastreabilidade).
                </p>
              </div>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel
              onClick={() => setManual((s) => ({ ...s, open: false }))}
              className="border-[#57715B]/20 hover:bg-[#57715B]/10"
            >
              Cancelar
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={() => void confirmManual()}
              className="bg-[#57715B] hover:bg-[#465b49] text-white"
            >
              Confirmar
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </Dialog>
  );
}

function Stat({
  label,
  value,
  icon,
}: {
  label: string;
  value: string | number;
  icon?: React.ReactNode;
}) {
  return (
    <div className="text-center min-w-0">
      <p className="text-[9px] sm:text-[10px] uppercase tracking-widest text-muted-foreground font-bold truncate flex items-center gap-1 justify-center">
        {icon}
        {label}
      </p>
      <p className="text-xl sm:text-2xl font-black tabular-nums text-[#57715B]">{value}</p>
    </div>
  );
}

function ItemRow({
  item,
  onMarcarManual,
}: {
  item: ChegadaItem;
  onMarcarManual: () => void;
}) {
  const recebido = Number(item.quantidade_recebida || "0") || 0;
  const solicitado = item.quantidade_solicitada || 0;
  const enviado = Number(item.quantidade_enviada || "0") || 0;
  const pct = solicitado > 0 ? Math.min(100, Math.round((recebido / solicitado) * 100)) : 0;
  const status: "vazio" | "parcial" | "completo" | "excesso" =
    recebido === 0
      ? "vazio"
      : recebido > solicitado
        ? "excesso"
        : recebido >= solicitado
          ? "completo"
          : "parcial";
  const ring =
    status === "completo"
      ? "border-emerald-500/40 bg-emerald-500/5"
      : status === "excesso"
        ? "border-amber-500/40 bg-amber-500/5"
        : status === "parcial"
          ? "border-[#57715B]/30 bg-[#57715B]/5"
          : "border-white/30 dark:border-white/10";
  const bg =
    status === "completo"
      ? "bg-emerald-500"
      : status === "excesso"
        ? "bg-amber-500"
        : status === "parcial"
          ? "bg-[#57715B]"
          : "bg-zinc-300 dark:bg-zinc-700";
  return (
    <div className={cn("rounded-xl border-2 p-3", ring)}>
      <div className="flex items-start justify-between gap-2 mb-1.5">
        <div className="min-w-0 flex-1">
          <p className="text-sm font-semibold leading-tight truncate flex items-center gap-2">
            {status === "completo" && (
              <CheckCircle2 className="w-4 h-4 text-emerald-600 flex-shrink-0" />
            )}
            {status === "excesso" && (
              <AlertTriangle className="w-4 h-4 text-amber-600 flex-shrink-0" />
            )}
            <span className="truncate">{item.nome_produto}</span>
          </p>
          <p className="text-[11px] text-muted-foreground mt-0.5">
            Pedido <b>{solicitado}</b> un · Expedido <b>{enviado || 0}</b> un
            {item.recebida_via && (
              <span
                className={cn(
                  "ml-2 inline-block px-1.5 py-0.5 rounded text-[9px] font-bold uppercase tracking-wider",
                  item.recebida_via === "bip"
                    ? "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-300"
                    : "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-300",
                )}
              >
                {item.recebida_via}
              </span>
            )}
          </p>
        </div>
        <div className="flex items-center gap-2 flex-shrink-0">
          <span
            className={cn(
              "text-sm font-bold tabular-nums",
              status === "completo"
                ? "text-emerald-700"
                : status === "excesso"
                  ? "text-amber-700"
                  : "text-foreground",
            )}
          >
            {recebido}/{solicitado}
          </span>
          <Button
            data-mia-action="marcar-manual"
            size="sm"
            variant="outline"
            className="h-8 gap-1 text-[11px] border-[#57715B]/20 hover:bg-[#57715B]/10"
            onClick={onMarcarManual}
          >
            <Hand className="w-3 h-3" /> Manual
          </Button>
        </div>
      </div>
      <div className="w-full h-1.5 bg-zinc-100 dark:bg-zinc-800 rounded-full overflow-hidden">
        <div
          className={cn("h-full rounded-full transition-all duration-500", bg)}
          style={{ width: `${pct}%` }}
        />
      </div>
    </div>
  );
}

input.content:
/**
 * Página de Conferência & Recebimento — exclusiva para lojistas.
 *
 * Lista as requisições da loja do usuário logado. Para cada requisição:
 *  - Exibe progresso de conferência (itens conferidos/total)
 *  - Permite rastrear expedição via StoreExpeditionTracker
 *  - Permite conferir chegada via RequisicaoChegadaModal (com o fix anti-double-count)
 *
 * Filtro: requisicoes.loja_solicitante ilike '%{nome da loja}%'
 * Loja ativa: StoreContext → selectedStore
 */
import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { Loader2, Package, PackageCheck, RefreshCw, ScanBarcode, Truck } from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { toast } from "sonner";

import { MommaPageLayout } from "@/components/layout/MommaPageLayout";
import { Button } from "@/shared/ui/button";
import { cn } from "@/shared/lib/utils";
import { supabase } from "@/integrations/supabase/client";
import { useStore } from "@/shared/contexts/StoreContext";
import { normalizeRequisicaoStatus } from "@/shared/lib/logistics-utils";

import { StoreExpeditionTracker } from "@/features/logistica/ui/StoreExpeditionTracker";
import { type ChegadaItem, RequisicaoChegadaModal } from "./RequisicaoChegadaModal";

// ─── Tipos internos ────────────────────────────────────────────────────────────

interface RequisicaoItemRaw {
  id: number;
  nome_produto: string;
  produto_master_id: number | null;
  quantidade_solicitada: number | null;
  quantidade_enviada: string | null;
  quantidade_recebida: string | null;
  recebida_via: string | null;
  recebida_at: string | null;
}

interface RequisicaoRaw {
  id: number;
  nome: string;
  status: string;
  loja_solicitante: string;
  created_at: string;
  expedicao_id: string | null;
  chegada_concluida_at: string | null;
  requisicoes_itens: RequisicaoItemRaw[];
}

interface ExpeditionState {
  expeditionId: string;
  storeName: string;
}

// ─── Helpers ───────────────────────────────────────────────────────────────────

function calcProgresso(items: RequisicaoItemRaw[]) {
  const total = items.length;
  const conferidos = items.filter(
    (i) => (Number(i.quantidade_recebida || 0) || 0) > 0,
  ).length;
  return { total, conferidos };
}

function toChegadaItems(items: RequisicaoItemRaw[]): ChegadaItem[] {
  return items.map((item) => ({
    id: item.id,
    nome_produto: item.nome_produto,
    masterId: item.produto_master_id,
    quantidade_solicitada: item.quantidade_solicitada ?? 0,
    quantidade_enviada: String(item.quantidade_enviada ?? 0),
    quantidade_recebida: String(item.quantidade_recebida ?? 0),
    recebida_via: item.recebida_via as "bip" | "manual" | null,
    recebida_at: item.recebida_at,
  }));
}

type BadgeStatus = "recebida" | "expedida" | "separando" | "aguardando";

function resolverBadgeStatus(req: RequisicaoRaw): BadgeStatus {
  if (req.chegada_concluida_at) return "recebida";
  const norm = normalizeRequisicaoStatus(req.status);
  if (norm === "finalizada") return "expedida";
  if (norm === "em_progresso") return "separando";
  return "aguardando";
}

function StatusBadge({ status }: { status: BadgeStatus }) {
  const map: Record<BadgeStatus, { label: string; className: string }> = {
    recebida: {
      label: "Recebida",
      className: "text-emerald-600 bg-emerald-50 dark:bg-emerald-900/20",
    },
    expedida: {
      label: "Expedida",
      className: "text-blue-600 bg-blue-50 dark:bg-blue-900/20",
    },
    separando: {
      label: "Separando",
      className: "text-amber-600 bg-amber-50 dark:bg-amber-900/20",
    },
    aguardando: {
      label: "Aguardando",
      className: "text-gray-500 bg-gray-50 dark:bg-gray-900/20",
    },
  };
  const { label, className } = map[status];
  return (
    <span
      className={cn(
        "inline-block px-2 py-0.5 rounded-full text-[11px] font-semibold uppercase tracking-wider",
        className,
      )}
    >
      {label}
    </span>
