          </p>
        )}
      </div>

      {/* Linha 3: barra de progresso */}
      {total > 0 && (
        <div className="w-full h-1.5 bg-zinc-100 dark:bg-zinc-800 rounded-full overflow-hidden mb-3">
          <div
            className={cn(
              "h-full rounded-full transition-all duration-500",
