          )}
        >
          <Truck className="w-3.5 h-3.5" />
          Rastrear
        </Button>
        <Button
          size="sm"
          onClick={onConferir}
          className="h-9 gap-1.5 flex-1 text-[12px] bg-[#57715B] hover:bg-[#465b49] text-white"
        >
          <ScanBarcode className="w-3.5 h-3.5" />
          Conferir chegada
        </Button>
      </div>
    </div>
  );
}

