diff --git a/src/features/requisicoes/ui/RequisicaoChegadaModal.tsx b/src/features/requisicoes/ui/RequisicaoChegadaModal.tsx
index d6739390..5fc0d81f 100644
--- a/src/features/requisicoes/ui/RequisicaoChegadaModal.tsx
+++ b/src/features/requisicoes/ui/RequisicaoChegadaModal.tsx
@@ -3,15 +3,15 @@
  *
  * Quando o caminhão chega na loja destino, o operador entra com a requisição
  * carregada (apenas itens da requisição da própria loja). Para cada item:
- *  - Bipa o QR da caixa → RPC bipar_etiqueta(uid,'entrada',{loja_id})
- *    + INSERT movimentacao + atualiza requisicoes_itens.quantidade_recebida
- *    + recebida_via='bip', recebida_at, recebida_por.
+ *  - Bipa o QR da caixa → RPC marcar_conferencia_requisicao(uid, requisicaoId, lojaId, meta)
+ *    APENAS MARCAÇÃO — não mexe em estoque. Atualiza requisicoes_itens.quantidade_recebida.
  *  - OU marca manual (sem etiqueta): apenas atualiza recebida_via='manual'
- *    + quantidade_recebida = quantidade_solicitada (sem mexer em movimentacoes,
- *    o estoque entra via fluxo paralelo).
+ *    + quantidade_recebida = quantidade_solicitada (sem mexer em movimentacoes).
+ *
+ * Ao clicar "Finalizar e dar entrada": chama dar_entrada_requisicao(requisicaoId) UMA vez,
+ * que gera as movimentacoes de estoque de todas as etiquetas bipadas (idempotente).
  *
  * Salva parcial. Operador pode fechar e voltar depois — state hidrata da DB.
- * "Concluir chegada" preenche requisicoes.chegada_concluida_at.
  */
 import { useEffect, useMemo, useRef, useState } from "react";
 import { Dialog, DialogContent, DialogTitle } from "@/shared/ui/dialog";
@@ -31,7 +31,7 @@ import { cn } from "@/shared/lib/utils";
 import { supabase } from "@/integrations/supabase/client";
 import {
   useEtiquetaScanner, playSuccessSound, playErrorSound, playWarningSound,
-  formatBipError, type ScannedPayload,
+  type ScannedPayload,
 } from "@/shared/hooks/useEtiquetaScanner";
 import { CameraScannerStatus } from "@/features/logistica/ui/CameraScannerStatus";

@@ -58,7 +58,6 @@ interface ManualState {
   open: boolean;
   item?: ChegadaItem;
   quantidade: string;
-  resolve?: (ok: boolean, qty: number) => void;
 }

 interface Props {
@@ -69,10 +68,19 @@ interface Props {
   lojaDestinoId: number;
   lojaDestinoNome: string;
   items: ChegadaItem[];
-  /** Quando o operador clica em "Concluir chegada" — pai recarrega/atualiza UI. */
+  /** Quando o operador clica em "Finalizar e dar entrada" — pai recarrega/atualiza UI. */
   onConcluida?: () => void;
 }

+interface DarEntradaResult {
+  ok: boolean;
+  etiquetas_processadas: number;
+  total_quantidade: number;
+  ja_processadas: number;
+  alertas: string[];
+  error?: string;
+}
+
 export function RequisicaoChegadaModal({
   isOpen, onClose, requisicaoId, requisicaoNome,
   lojaDestinoId, lojaDestinoNome, items, onConcluida,
@@ -82,6 +90,7 @@ export function RequisicaoChegadaModal({
   const uidsLidosRef = useRef<Set<string>>(new Set());
   const [manual, setManual] = useState<ManualState>({ open: false, quantidade: "" });
   const [concluindo, setConcluindo] = useState(false);
+  const [confirmandoFinalizar, setConfirmandoFinalizar] = useState(false);

   useEffect(() => {
     if (!isOpen) return;
@@ -131,46 +140,63 @@ export function RequisicaoChegadaModal({

     await marcarChegadaIniciada();

-    // RPC: valida transição em_transito → recebida
-    // eslint-disable-next-line @typescript-eslint/no-explicit-any
-    const { data: rpcRaw, error: rpcErr } = await (supabase.rpc as any)("bipar_etiqueta", {
-      p_uid: payload.uid,
-      p_etapa: "entrada",
-      p_contexto: {
-        loja_id: lojaDestinoId,
-        referencia_tipo: "requisicao_chegada",
-        referencia_id: String(requisicaoId),
-        payload,
+    // Buscar dados da etiqueta para saber produto e quantidade
+    const { data: etiquetaData, error: etiquetaErr } = await supabase
+      .from("etiquetas_qr")
+      .select("quantidade_interna, produto_master_id, lote_id")
+      .eq("uid", payload.uid)
+      .maybeSingle();
+
+    if (etiquetaErr) {
+      playErrorSound();
+      toast.error(`Falha ao ler etiqueta: ${etiquetaErr.message}`);
+      return;
+    }
+
+    const qty = Number(etiquetaData?.quantidade_interna ?? payload.qty ?? 1);
+    const masterId = etiquetaData?.produto_master_id ?? null;
+    const loteId = (etiquetaData as { lote_id?: string | null } | null)?.lote_id ?? null;
+
+    // RPC de marcação de conferência (NÃO mexe em estoque — só registra o bip)
+    // @ts-expect-error RPC nova ainda não regenerada nos tipos
+    const { data: marcRes, error: marcErr } = await (supabase.rpc as any)(
+      "marcar_conferencia_requisicao",
+      {
+        p_uid: payload.uid,
+        p_requisicao_id: requisicaoId,
+        p_loja_id: lojaDestinoId,
+        p_meta: {
+          quantidade_interna: qty,
+          produto_master_id: masterId,
+          lote_id: loteId,
+        },
       },
-    });
-    if (rpcErr) {
+    );

